import { SECTIONS, OPTIONS, DEFAULTS, DEMO_VALUES, RECOMMENDATION, getOption, valueLabel, searchOptions, changedOptions, isAvailable, createModel } from './model.mjs';

const $ = (s, r=document) => r.querySelector(s);
const $$ = (s, r=document) => [...r.querySelectorAll(s)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',trailers:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="m10 9 5 3-5 3Z"/>',languages:'<path d="M3 5h12M9 3v2M5 5c0 6 6 10 9 11M13 5c-1 6-5 10-10 12m11 4 4-11 4 11m-6-4h4"/>',performance:'<path d="M4 18a9 9 0 1 1 16 0M12 13l5-5"/><circle cx="12" cy="13" r="2"/><path d="M3 13h2m14 0h2M7 5l1 2m8-2-1 2"/>',changes:'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7M12 7v6l4 2"/>',chevron:'<path d="m9 5 7 7-7 7"/>',device:'<rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8m-4-4v4"/>',profile:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',check:'<path d="m4 12 5 5L20 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-11v2"/>',volume:'<path d="M10 5 5 9H2v6h3l5 4Zm4 3a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',spark:'<path d="m12 3 2.8 6.2L21 12l-6.2 2.8L12 21l-2.8-6.2L3 12l6.2-2.8Z"/>',back:'<path d="m10 5-7 7 7 7M3 12h18"/>'};
const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.info}</svg>`;
const STORAGE = 'nuvio-ajustes-ux-demo-v1';
let initial=DEMO_VALUES;
try { const raw=localStorage.getItem(STORAGE); if(raw) initial=JSON.parse(raw); } catch {}
let model; try {model=createModel(initial);} catch {model=createModel(DEMO_VALUES);}
const state={section:'trailers',advanced:false,query:'',focusId:'focusTrailer',revealed:null,modal:null,history:[],lastFocus:{},originKey:'opt-focusTrailer',timer:null,timerStart:0};
let toastTimer;
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function focusKey(key){const target=$(`[data-key="${CSS.escape(key)}"]`);if(target){target.focus({preventScroll:true});if(!target.closest('.navigation'))target.scrollIntoView({block:'nearest',behavior:'instant'});}return target;}
function section(id){return SECTIONS.find(s=>s.id===id);}
function persist(before){try{localStorage.setItem(STORAGE,JSON.stringify(model.saved));return true;}catch{model=createModel(before);toast('Não foi possível guardar a alteração. Seu valor anterior foi mantido.');return false;}}
function commit(message='Preferência atualizada.'){const before=model.saved;const changed=model.commit();if(!changed.length){closeModal();return;}const ok=persist(before);closeModal();if(ok)toast(message);}
function currentContext(){return {section:state.section,query:state.query,revealed:state.revealed,focusKey:document.activeElement?.dataset.key||state.originKey,scroll:$('.option-list')?.scrollTop||0};}
function restoreContext(c){state.section=c.section;state.query=c.query;state.revealed=c.revealed;render();if($('.option-list'))$('.option-list').scrollTop=c.scroll||0;focusKey(c.focusKey)||focusKey(`nav-${state.section}`);}
function scopeText(o){return o.scope==='profile'?'Preferência do seu perfil':'Somente nesta TV';}
function nav(){const selected=state.section;const count=changedOptions(model.saved).length;const items=[{id:'search',label:'Buscar ajustes',icon:'search'},{id:'changes',label:'Diferente do padrão',icon:'changes'},...SECTIONS.map(s=>({...s,icon:s.id}))];$('#navigation').innerHTML=items.map((s,i)=>`${i===2?'<div class="nav-separator"></div>':''}<button class="nav-item ${selected===s.id?'active':''}" data-zone="nav" data-action="section" data-section="${s.id}" data-key="nav-${s.id}" ${selected===s.id?'aria-current="page"':''}>${icon(s.icon)}<span>${esc(s.label)}</span>${s.id==='changes'?`<span class="count">${count}</span>`:''}</button>`).join('')+'<p class="nav-caption">Três seções para explorar.<br>Suas TVs não serão alteradas.</p>';}
function visibleOptions(){if(state.section==='search')return searchOptions(state.query);if(state.section==='changes')return changedOptions(model.saved);return OPTIONS.filter(o=>o.section===state.section&&(!o.advanced||state.advanced||o.id===state.revealed));}
function row(o){const av=isAvailable(o,model.saved);const diff=model.saved[o.id]!==DEFAULTS[o.id];const from=state.section==='search'||state.section==='changes';const sub=from?`${section(o.section).label}${o.advanced?' · Avançado':''}`:(!av.available?av.reason:'');return `<button class="option" data-action="${from?'jump':'edit'}" data-id="${o.id}" data-key="${from?'result':'opt'}-${o.id}" data-zone="list" data-unavailable="${!av.available}" aria-label="${esc(o.label+', '+valueLabel(o.id,model.saved[o.id]))}"><span><span class="label">${esc(o.label)}${diff?'<i class="changed-dot" aria-label="Diferente do padrão"></i>':''}</span>${sub?`<span class="subline">${esc(sub)}</span>`:''}</span><span class="value">${esc(valueLabel(o.id,model.saved[o.id]))}${icon('chevron')}</span></button>`;}
function rows(){const opts=visibleOptions();let lastGroup='';let html='';if(state.section==='performance')html=`<button class="option recommendation" data-action="recommend" data-zone="list" data-key="recommendation"><span><span class="label">Experimentar menos efeitos</span><span class="subline">Veja o que muda antes de decidir.</span></span>${icon('spark')}</button>`;
 if(state.section==='search'&&!state.query.trim()){html=`<div class="empty-state">${icon('search')}<h3>O que você quer ajustar?</h3><p>Procure pelo efeito que deseja, como “dublado”, “trailer” ou “memória”.</p><div class="chip-list">${['trailer','dublado','memória'].map(t=>`<button class="chip" data-action="query" data-query="${t}" data-zone="list" data-key="query-${t}">${t}</button>`).join('')}</div></div>`;}
 else if(!opts.length){html=`<div class="empty-state">${icon(state.section==='changes'?'check':'search')}<h3>${state.section==='changes'?'Tudo no padrão.':'Nenhum ajuste encontrado.'}</h3><p>${state.section==='changes'?'As preferências diferentes dos padrões da demonstração aparecerão aqui, incluindo as avançadas.':'Tente outro termo. A busca também encontra ajustes avançados.'}</p></div>`;}
 else{if(state.revealed&&!state.advanced&&getOption(state.revealed)?.advanced)html+='<p class="revealed-note">Este ajuste avançado foi revelado pela busca.</p>';for(const o of opts){const grouped=state.section!=='search'&&state.section!=='changes';if(grouped&&o.group!==lastGroup){lastGroup=o.group;html+=`<p class="group-label">${esc(o.group)}</p>`;}html+=row(o);}}
 $('#option-list').innerHTML=html;
}
function content(){const search=state.section==='search',changes=state.section==='changes';const s=section(state.section);$('#content').innerHTML=`<div class="section-head"><div><h2>${search?'Buscar ajustes':changes?'Diferente do padrão':esc(s.label)}</h2><p>${search?'Encontre pelo nome ou pelo que quer mudar.':changes?'Suas preferências, comparadas ao padrão.':esc(s.description)}</p></div>${!search&&!changes?`<button class="advanced-toggle ${state.advanced?'on':''}" data-action="advanced" data-zone="list" data-key="advanced" aria-pressed="${state.advanced}">Avançados<br>${state.advanced?'Visíveis':'Ocultos'}</button>`:''}</div>${search?`<label class="searchbox">${icon('search')}<input id="search-input" data-key="search-input" data-zone="search" placeholder="Trailer, idioma, memória…" autocomplete="off" aria-label="Buscar ajustes" value="${esc(state.query)}"></label>`:''}<div id="option-list" class="option-list"></div>`;rows();}
function scene(o,values){
 const kind=o?.preview||'trailer';
 if(kind==='language'){
  let lang=values[o.id];if(lang==='interface')lang=values.uiLang;
  const en=lang==='en'||lang==='original',sp=lang==='es';
  let example=en?'We can find a way.':sp?'Podemos encontrar una solución.':'Podemos encontrar um caminho.';
  let label='Amostra de legenda';
  if(o.id==='uiLang'){example=en?'Continue watching':sp?'Seguir viendo':'Continuar assistindo';label='Amostra dos menus';}
  if(o.id==='metadataLang'){example=en?'The Martian':sp?'Marte':'Perdido em Marte';label='Amostra do título';}
  if(o.id==='audioLang'){example=valueLabel(o.id,values[o.id]);label='Faixa de áudio preferida';}
  return `<div class="preview-scene"><img src="assets/scene.jpg" alt="Cena de exemplo de Perdido em Marte"><span class="preview-badge">${esc(label)}</span><div class="preview-language"><span>${o.id==='audioLang'?'♫ ':''}${esc(example)}</span></div></div>`;
 }
 if(kind==='performance')return `<div class="preview-scene"><img src="assets/scene.jpg" alt="Exemplo de tela inicial"><span class="preview-badge">${values.resolution==='720'?'720p':values.resolution==='2160'?'4K':'1080p'} · exemplo visual</span><div class="performance-sample ${values.glass==='off'?'noglass':''}"><img src="assets/poster-1.jpg" alt=""><img src="assets/poster-2.jpg" alt=""><div class="mini-text">Continuar assistindo<small>${values.glass==='off'?'Painel sólido':'Painel com vidro'}</small></div></div></div>`;
 let active=values[o.id]==='on',badge=active?'Trailer permitido':'Imagem estática';
 if(o.id==='heroSound'||o.id==='detailSound'){active=values[o.requires]==='on';badge=active?(values[o.id]==='on'?'Trailer com som':'Trailer sem som'):'Trailer desativado';}
 if(['trailerSource','trailerDelay','trailerQuality'].includes(o.id)){active=values.heroTrailer==='on';badge=valueLabel(o.id,values[o.id]);}
 return `<div class="preview-scene"><img src="assets/scene.jpg" alt="Arte de Perdido em Marte usada na prévia"><span class="preview-badge">${icon(active?'trailers':'device')}${esc(badge)}</span><div class="preview-caption"><small>Exemplo ilustrativo</small>Perdido em Marte</div>${active?'<div class="mini-timeline"></div>':''}</div>`;
}

function inspector(){let o=getOption(state.focusId);if(!o)o=visibleOptions()[0]||OPTIONS[0];const values=model.previewValues();const selected=o.values.find(v=>v.value===values[o.id]);const alt=o.values.find(v=>v.value!==values[o.id]);$('#inspector').innerHTML=`${scene(o,values)}<h3>${esc(o.label)}</h3><p class="explanation">${esc(selected?.description||o.description)}</p>${alt?`<p class="alternative">${esc(alt.label)}: ${esc(alt.description||'você pode escolher na próxima tela.')}</p>`:''}<dl><div><dt>Vale para</dt><dd>${o.scope==='profile'?'Seu perfil':'Esta TV'}</dd></div><div><dt>Padrão</dt><dd>${esc(valueLabel(o.id,DEFAULTS[o.id]))}</dd></div></dl><p class="help-hint"><kbd>OK</kbd> Ver opções e detalhes</p>`;}
function render(){nav();content();inspector();}
function selectSection(id,focus=true){if(state.modal)return;if(document.activeElement?.dataset.zone==='list')state.lastFocus[state.section]=document.activeElement.dataset.key;state.section=id;state.revealed=null;state.history=[];render();if(focus){if(id==='search')focusKey('search-input');else focusKey(state.lastFocus[id])||focusKey(id==='performance'?'recommendation':(id==='changes'?'result-':'opt-')+visibleOptions()[0]?.id)||focusKey(`nav-${id}`);}}
function jump(id){state.history.push(currentContext());const o=getOption(id);state.section=o.section;state.revealed=id;state.focusId=id;render();focusKey(`opt-${id}`);}
function goBack(){if(state.modal){closeModal();return;}if(state.history.length){restoreContext(state.history.pop());return;}const el=document.activeElement;if(el?.dataset.zone==='nav'){openHome();return;}focusKey(`nav-${state.section}`);}
function captureOrigin(){state.originScroll=$('.option-list')?.scrollTop||0;state.originKey=document.activeElement?.dataset.key||`opt-${state.focusId}`;}
function openOption(id){const o=getOption(id);captureOrigin();state.focusId=id;const av=isAvailable(o,model.saved);if(!av.available){state.modal={type:'unavailable',id,requires:av.requires||o.requires};renderModal();return;}model.begin({[id]:model.saved[id]});state.modal={type:'edit',id};renderModal();focusKey(`choice-${model.saved[id]}`);}
function modalShell(title,lead,body,footer='',scope=''){return `<div class="overlay"><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="sheet-topline"><span>${esc(scope||'Ajustes')}</span><button data-action="close" data-zone="modal" data-key="modal-close" aria-label="Cancelar e voltar">×</button></div><h2 id="dialog-title">${esc(title)}</h2>${lead?`<p class="lead">${esc(lead)}</p>`:''}${body}${footer}</section></div>`;}
function renderModal(){const m=state.modal;if(!m){$('#overlay-root').innerHTML='';$('#tv').inert=false;$('#reset-demo').disabled=false;$('#help-button').disabled=false;return;}$('#tv').inert=true;$('#reset-demo').disabled=true;$('#help-button').disabled=true;let html='';
 if(m.type==='edit'){const o=getOption(m.id);const saved=model.saved[o.id];const note=o.scope==='profile'?'No app, esta preferência acompanha seu perfil nas outras TVs.':'Esta escolha vale somente para este aparelho.';html=modalShell(o.label,o.description,`<div class="scope-note">${icon(o.scope==='profile'?'profile':'device')}<span>${note}</span></div><div class="editor-layout"><div class="choices">${o.values.map(v=>`<button class="choice" data-action="choose" data-id="${o.id}" data-value="${esc(v.value)}" data-zone="modal" data-key="choice-${esc(v.value)}"><span><strong>${esc(v.label)}</strong>${v.description?`<small>${esc(v.description)}</small>`:''}</span><span class="check">${v.value===saved?'✓':''}</span></button>`).join('')}</div><div class="editor-preview"><div id="candidate-preview">${scene(o,model.previewValues())}</div><p>Prévia da escolha<br><small>Ainda não aplicada</small></p></div></div>`,`<div class="sheet-footer"><span class="hint"><kbd>OK</kbd> Aplicar escolha<br><kbd>Esc</kbd> Cancelar · ✓ valor salvo</span><button class="text-button" data-action="restore" data-id="${o.id}" data-zone="modal" data-key="restore">Restaurar padrão</button></div>`,scopeText(o));}
 if(m.type==='restore'){const o=getOption(m.id);html=modalShell('Restaurar este ajuste?',o.label,`<div class="change-summary"><span>${esc(valueLabel(o.id,model.saved[o.id]))}</span><span class="destination">${icon('chevron')} ${esc(valueLabel(o.id,DEFAULTS[o.id]))}</span></div><p class="lead">${o.scope==='profile'?'No app, a restauração também pode alterar esta preferência nas outras TVs que usam o mesmo perfil.':'Somente esta preferência do aparelho será restaurada.'}</p><div class="action-buttons"><button class="secondary-button" data-action="cancel-restore" data-zone="modal" data-key="cancel-restore">Cancelar</button><button class="primary-button" data-action="confirm-restore" data-id="${o.id}" data-zone="modal" data-key="confirm-restore">Restaurar padrão</button></div>`);}
 if(m.type==='unavailable'){const o=getOption(m.id);const req=getOption(m.requires);html=modalShell(o.label,'Este ajuste precisa de outra preferência ativada.',`<div class="scope-note">${icon('info')}<span>${esc(isAvailable(o,model.saved).reason)}</span></div><div class="action-buttons"><button class="secondary-button" data-action="close" data-zone="modal" data-key="cancel-unavailable">Voltar</button>${req?`<button class="primary-button" data-action="requirement" data-id="${req.id}" data-zone="modal" data-key="requirement">Abrir ${esc(req.label.toLowerCase())}</button>`:''}</div>`);}
 if(m.type==='recommend'){html=modalShell('Uma tela com menos efeitos','Experimente estas mudanças por 15 segundos. Você decide se quer manter.',`<div class="scope-note">${icon('device')}<span>Somente nesta TV. Áudio, trailers e preferências do perfil continuam como estão.</span></div>${Object.entries(RECOMMENDATION.changes).filter(([id,v])=>model.saved[id]!==v).map(([id,v])=>`<div class="change-summary"><span>${esc(getOption(id).label)}<br><small>${esc(valueLabel(id,model.saved[id]))}</small></span><span class="destination">${esc(valueLabel(id,v))}</span></div>`).join('')}<div class="action-buttons"><button class="secondary-button" data-action="close" data-zone="modal" data-key="cancel-recommend">Agora não</button><button class="primary-button" data-action="experiment-recommend" data-zone="modal" data-key="experiment-recommend">Experimentar</button></div>`);}
 if(m.type==='experiment'){const values=model.previewValues();html=`<div class="overlay experiment-overlay"><div class="experiment-scene"></div><div class="experiment-home"><h2>Perdido<br>em Marte.</h2><p>2015 · Ficção científica · Aventura</p><div class="experiment-posters ${values.glass==='off'?'noglass':''}">${[1,2,3].map(i=>`<img src="assets/poster-${i}.jpg" alt="Cartaz de exemplo">`).join('')}</div></div><section class="sheet experiment-sheet" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="sheet-topline"><span>Experimentando nesta TV</span></div><h2 id="dialog-title">Gostou de como ficou?</h2><p class="lead">Se preferir, volte à sua configuração anterior. Nada é salvo até você manter.</p><div class="timer"><span id="timer-label">Preparando a prévia…</span><span class="countdown" id="countdown">—</span></div><div class="countdown-track"><div id="timer-bar"></div></div><div class="action-buttons"><button class="secondary-button" data-action="cancel-experiment" data-zone="modal" data-key="cancel-experiment">Voltar ao anterior</button><button class="primary-button" data-action="keep" data-zone="modal" data-key="keep" disabled>Manter</button></div></section><span class="experiment-tag">Prévia ilustrativa · não mede desempenho da TV</span></div>`;}
 if(m.type==='help'){html=modalShell('Use como um controle de TV','Clique na tela e navegue pelo teclado.',`<div class="help-grid"><kbd>↑ ↓</kbd><span>Percorrer seções, ajustes ou escolhas.</span><kbd>← →</kbd><span>Entrar ou voltar entre seções e lista.</span><kbd>Enter</kbd><span>OK: abrir opções ou confirmar uma escolha.</span><kbd>Esc</kbd><span>Voltar. Uma escolha ainda não confirmada é descartada.</span></div><p class="lead">Busca, comparação e gravação usam apenas os dados desta demonstração no navegador. Não há reprodução de vídeo nem conexão com sua conta.</p><div class="action-buttons"><button class="primary-button" data-action="close" data-zone="modal" data-key="help-close">Começar</button></div>`);}
 if(m.type==='home'){html=modalShell('Você voltou à tela inicial','O retorno preserva o lugar em que você estava nos ajustes.',`<div class="preview-scene"><img src="assets/scene.jpg" alt="Exemplo de tela inicial"></div><div class="action-buttons"><button class="primary-button" data-action="close" data-zone="modal" data-key="home-close">Voltar aos ajustes</button></div>`);}
 if(m.type==='reset-demo'){html=modalShell('Reiniciar a demonstração?','Isso restaura apenas os exemplos deste protótipo.',`<div class="action-buttons"><button class="secondary-button" data-action="close" data-zone="modal" data-key="reset-cancel">Cancelar</button><button class="primary-button" data-action="confirm-demo-reset" data-zone="modal" data-key="reset-confirm">Reiniciar</button></div>`);}
 $('#overlay-root').innerHTML=html;requestAnimationFrame(()=>{if(state.modal?.type===m.type){const target=m.type==='edit'?`choice-${model.saved[m.id]}`:m.type==='experiment'?'cancel-experiment':m.type==='restore'?'cancel-restore':m.type==='recommend'?'experiment-recommend':m.type==='unavailable'?'cancel-unavailable':m.type==='help'?'help-close':m.type==='home'?'home-close':'reset-cancel';focusKey(target);}});
}
function clearTimers(){if(state.timer)clearInterval(state.timer);state.timer=null;clearTimeout(state.applyTimeout);state.applyTimeout=null;}
function closeModal(){const wasExperiment=state.modal?.type==='experiment';clearTimers();model.cancel();state.modal=null;renderModal();render();if($('.option-list'))$('.option-list').scrollTop=state.originScroll||0;focusKey(state.originKey)||focusKey(`nav-${state.section}`);if(wasExperiment)toast('Configuração anterior mantida.');}
function openHome(){captureOrigin();state.modal={type:'home'};renderModal();}
async function startExperiment(changes){model.begin(changes);state.modal={type:'experiment'};renderModal();const token=Symbol();state.experimentToken=token;const fail=()=>{if(state.modal?.type==='experiment'&&state.experimentToken===token){closeModal();toast('A prévia não ficou pronta. A configuração anterior foi mantida.');}};state.applyTimeout=setTimeout(fail,5000);const img=new Image();img.src='assets/scene.jpg';try{await img.decode();}catch{fail();return;}await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));if(state.modal?.type!=='experiment'||state.experimentToken!==token)return;clearTimeout(state.applyTimeout);state.applyTimeout=null;state.timerStart=performance.now();$('#timer-label').textContent='Voltaremos ao anterior em';$('[data-action="keep"]').disabled=false;
 const tick=()=>{if(state.modal?.type!=='experiment')return;const left=Math.max(0,15-(performance.now()-state.timerStart)/1000);$('#countdown').textContent=Math.ceil(left)+' s';$('#timer-bar').style.width=(left/15*100)+'%';if(left===0){closeModal();toast('O tempo terminou. Configuração anterior mantida.');}};tick();state.timer=setInterval(tick,150);}
function choose(id,value){model.candidate(id,value);if(getOption(id).section==='performance'&&value!==model.saved[id]){startExperiment({[id]:value});return;}commit();}
function restoreFromEditor(id){model.cancel();state.modal={type:'restore',id};renderModal();}
function action(el){const a=el.dataset.action,id=el.dataset.id;switch(a){case 'section':selectSection(el.dataset.section);break;case 'advanced':state.advanced=!state.advanced;state.revealed=null;render();focusKey('advanced');break;case 'edit':openOption(id);break;case 'jump':jump(id);break;case 'query':state.query=el.dataset.query;content();focusKey('search-input');break;case 'choose':choose(id,el.dataset.value);break;case 'close':case 'cancel-experiment':closeModal();break;case 'restore':restoreFromEditor(id);break;case 'cancel-restore':state.modal={type:'edit',id:state.modal.id};model.begin({[state.modal.id]:model.saved[state.modal.id]});renderModal();break;case 'confirm-restore':model.begin({[id]:DEFAULTS[id]});if(getOption(id).section==='performance'&&DEFAULTS[id]!==model.saved[id])startExperiment({[id]:DEFAULTS[id]});else commit('Vale novamente o padrão deste ajuste.');break;case 'recommend':captureOrigin();state.modal={type:'recommend'};renderModal();break;case 'experiment-recommend':startExperiment(RECOMMENDATION.changes);break;case 'keep':clearTimers();state.modal={type:'committing'};commit('Nova configuração mantida.');break;case 'requirement':{const req=id;closeModal();jump(req);break;}case 'confirm-demo-reset':{const before=model.saved;model=createModel(DEMO_VALUES);if(persist(before)){state.section='trailers';state.query='';state.history=[];state.advanced=false;state.focusId='focusTrailer';state.originKey='opt-focusTrailer';}closeModal();toast('Demonstração reiniciada.');break;}}
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled)action(el);});
document.addEventListener('focusin',e=>{const el=e.target;if(el.dataset.zone==='list'&&el.dataset.id){state.focusId=el.dataset.id;state.lastFocus[state.section]=el.dataset.key;inspector();}if(el.classList.contains('choice')&&state.modal?.type==='edit'){model.candidate(el.dataset.id,el.dataset.value);const pv=$('#candidate-preview');if(pv)pv.innerHTML=scene(getOption(el.dataset.id),model.previewValues());}});
document.addEventListener('input',e=>{if(e.target.id==='search-input'){state.query=e.target.value;rows();const first=visibleOptions()[0];if(first){state.focusId=first.id;inspector();}}});
document.addEventListener('keydown',e=>{if(e.isComposing)return;const el=document.activeElement;const k=e.key;const isInput=el?.tagName==='INPUT';if(k==='Escape'||(k==='Backspace'&&!isInput)){e.preventDefault();goBack();return;}if(k==='Tab'&&state.modal){const controls=$$('[data-zone="modal"]:not(:disabled)');const i=controls.indexOf(el);e.preventDefault();controls[(i+(e.shiftKey?-1:1)+controls.length)%controls.length]?.focus();return;}if(k==='Enter'&&isInput){e.preventDefault();$$('[data-zone="list"]')[0]?.focus();return;}if(!k.startsWith('Arrow'))return;if(isInput&&k!=='ArrowDown')return;
 const zone=state.modal?'modal':el?.dataset.zone;e.preventDefault();if(isInput){$$('[data-zone="list"]')[0]?.focus();return;}if(zone==='modal'){const controls=$$('[data-zone="modal"]:not(:disabled)');const i=controls.indexOf(el);const delta=k==='ArrowDown'||k==='ArrowRight'?1:-1;controls[Math.max(0,Math.min(controls.length-1,i+delta))]?.focus();return;}if(zone==='nav'&&(k==='ArrowRight')){selectSection(el.dataset.section);return;}if(zone==='list'&&k==='ArrowLeft'){focusKey(`nav-${state.section}`);return;}if(k==='ArrowLeft'||k==='ArrowRight')return;const controls=$$(`[data-zone="${zone==='nav'?'nav':'list'}"]`);const i=controls.indexOf(el);if(zone==='list'&&i===0&&k==='ArrowUp'&&state.section==='search'){focusKey('search-input');return;}const j=Math.max(0,Math.min(controls.length-1,i+(k==='ArrowDown'?1:-1)));controls[j]?.focus();});
$('#reset-demo').addEventListener('click',()=>{captureOrigin();state.modal={type:'reset-demo'};renderModal();});
$('#help-button').addEventListener('click',()=>{captureOrigin();state.modal={type:'help'};renderModal();});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.modal?.type==='experiment')closeModal();});
window.addEventListener('pagehide',()=>{clearTimers();model.cancel();});
render();requestAnimationFrame(()=>focusKey('opt-focusTrailer'));
// Read-only snapshot for reproducible local prototype checks; it never accesses the app or an account.
window.prototypeSnapshot=()=>({saved:model.saved,draft:model.draft,section:state.section,advanced:state.advanced,query:state.query,modal:state.modal?.type||null,focused:document.activeElement?.dataset.key||null});
